import{_ as t,o as s,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"1. Qu'est-ce que Teuthis-CMS ?","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"1. Qu'est-ce que Teuthis-CMS ?","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/notice/1-qu-est-ce-que-teuthis-cms.md","filePath":"documentation/notice/1-qu-est-ce-que-teuthis-cms.md"}`),u={name:"documentation/notice/1-qu-est-ce-que-teuthis-cms.md"};function o(r,e,a,c,l,d){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="1-quest-ce-que-teuthis-cms-" tabindex="-1">1. Qu&#39;est-ce que Teuthis-CMS ? <a class="header-anchor" href="#1-quest-ce-que-teuthis-cms-" aria-label="Permalink to &quot;1. Qu&#39;est-ce que Teuthis-CMS ? {#1-quest-ce-que-teuthis-cms-}&quot;">​</a></h1><p>Teuthis-CMS est un logiciel de gestion de contenu (CMS) libre et gratuit, pensé pour les sites web des collectivités et administrations françaises, mais utilisable par toute organisation. Trois engagements structurent le produit :</p><ul><li><strong>Fonctionne entièrement sans intelligence artificielle.</strong> L&#39;IA est une option qu&#39;on peut activer plus tard ; aucune fonction essentielle du site n&#39;en dépend. Une instance installée sans rien configurer côté IA est pleinement opérationnelle.</li><li><strong>Rien ne se code.</strong> Créer un type de contenu (une rubrique « Actualités », un « Annuaire des services », un formulaire de demande), composer une page, gérer les droits d&#39;accès : tout se fait depuis le back-office, sans écrire une ligne de code ni faire de migration de base de données.</li><li><strong>Conçu pour la conformité française</strong> : RGPD, accessibilité numérique (déclaration générée), gestion des cookies, et une architecture pensée pour la protection des données personnelles (journalisation des accès, séparation stricte des comptes agents et des comptes usagers).</li></ul><p><strong>Ce que ce dépôt ne livre pas : le site public.</strong> Teuthis-CMS fournit le moteur (l&#39;API) et le back-office qui l&#39;administre ; le site que voient vos visiteurs — thème, gabarits, pages publiques — reste à réaliser ou à brancher sur l&#39;API. Les comportements décrits plus loin du point de vue d&#39;un visiteur (bandeau d&#39;alerte en tête de page, bloc qui se masque quand sa source est vide, recherche « autour de moi », page de suivi d&#39;un dossier) désignent ce que l&#39;API expose et ce que le back-office pilote, pas un rendu livré avec le produit.</p><p>Le projet est distribué sous licence libre Apache 2.0 — voir <code>LICENSE</code>.</p>',5)])])}const q=t(u,[["render",o]]);export{m as __pageData,q as default};
